using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Planner.Core;
using Planner.Data;
using Planner.Desktop;
static class SoftWindowChecks
{
 public static async Task Run(MainWindow main,PlannerViewModel vm,ScheduleBoard board,string directory,Action<bool,string> check)
 {
  string state=JsonSerializer.Serialize(vm.State,JsonKit.Options);
  main.SetLayoutMode("AUTO");main.Height=800;main.Width=1000;await Task.Delay(100);check(main.IsCompact&&board.ViewMode=="AGENDA","缩窄窗口自动进入简洁日程");
  main.Width=1140;await Task.Delay(60);check(main.IsCompact,"自动切换在临界区保留简洁状态");main.Width=1300;await Task.Delay(80);check(!main.IsCompact,"扩大窗口恢复完整模式");main.Width=1140;await Task.Delay(60);check(!main.IsCompact,"自动切换在临界区保留完整状态");
  main.SetLayoutMode("COMPACT");main.Width=400;main.Height=780;await Task.Delay(100);check(main.IsCompact&&Walk(board).OfType<Border>().Count(b=>b.Tag is DateOnly)==7,"简洁模式展示当天和随后六天");check(!Walk(main).OfType<TextBlock>().Any(t=>t.Text=="智能行程助手"&&t.IsVisible),"简洁模式隐藏助手与两侧栏");Capture(main,Path.Combine(directory,"soft-compact.png"));
  var card=Walk(board).OfType<SwipeActivityCard>().First();string key=card.Entry.Occurrence.Key;bool original=vm.Appearance.Completed.Contains(key);bool important=vm.Appearance.Important.Contains(key);card.Star.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(vm.Appearance.Important.Contains(key)!=important&&vm.Appearance.Completed.Contains(key)==original,"简洁星标与完成独立");
  var anchor=card.GesturePosition(new(0,0));card.BeginSwipe(anchor);card.ContinueSwipe(new(anchor.X+70,anchor.Y));var parent=(UIElement)card.Parent;var local=card.PointFromScreen(parent.PointToScreen(new(anchor.X+70,anchor.Y)));check(Math.Abs(card.GesturePosition(local).X-(anchor.X+70))<1,"拖动时坐标使用稳定父容器避免位移反馈");card.EndSwipe(true);
  Swipe(card,100,0);await Task.Delay(260);check(vm.Appearance.Completed.Contains(key)!=original&&Math.Abs(card.Opacity-(card.IsCompleted? .55:1))<.03,"右滑完成并淡出动画");Swipe(card,100,0);await Task.Delay(260);check(vm.Appearance.Completed.Contains(key)==original,"再次右滑恢复原状态");Swipe(card,-100,0);Swipe(card,10,0);Swipe(card,3,100);card.BeginSwipe(new(0,0));card.ContinueSwipe(new(100,0));card.EndSwipe(true);check(vm.Appearance.Completed.Contains(key)==original,"左滑短滑竖滑和取消不改变状态");
  card.ContextMenu!.PlacementTarget=card;card.ContextMenu.IsOpen=true;await Task.Delay(50);var action=card.ContextMenu.Items.OfType<MenuItem>().First(i=>Equals(i.Header,original?"恢复未完成":"标记完成"));card.ContextMenu.IsOpen=false;action.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(vm.Appearance.Completed.Contains(key)!=original,"右键完成操作保留");Swipe(card,100,0);await Task.Delay(240);
  double titleSize=Walk(card).OfType<TextBlock>().First(t=>t.Text==card.Entry.Occurrence.Title).FontSize;vm.UpdateAppearance(p=>p.FontSize=18);await Task.Delay(70);var larger=Walk(board).OfType<SwipeActivityCard>().First(c=>c.Entry.Occurrence.Key==key);check(Walk(larger).OfType<TextBlock>().First(t=>t.Text==larger.Entry.Occurrence.Title).FontSize>titleSize,"字号设置实际放大卡片文字");
  ButtonOf(main,"Aa").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(50);var appearance=Application.Current.Windows.OfType<AppearanceWindow>().Single();Walk(appearance).OfType<Slider>().Single().Value=22;await Task.Delay(80);check(vm.Appearance.FontSize==22&&new BoardPreferenceStore(vm.DataDirectory).Load().FontSize==22,"外观滑块实时生效并持久化");main.Width=320;await Task.Delay(100);check(main.IsCompact&&board.ActualWidth>=280,"大字号下320宽简洁界面可用");Capture(main,Path.Combine(directory,"soft-compact-large-font.png"));appearance.Close();vm.UpdateAppearance(p=>p.FontSize=14);
  ButtonOf(main,"置顶").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(main.Topmost,"简洁模式可置顶");
  var empty=Walk(board).OfType<Button>().First(b=>Equals(b.Content,"暂无安排 · 点击添加"));empty.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(40);var editor=Application.Current.Windows.OfType<EditorWindow>().Single();Walk(editor).OfType<TextBox>().First(t=>Equals(t.Tag,"ActivityTitle")).Text="模式切换时保留";main.SetLayoutMode("FULL");await Task.Delay(90);check(!main.IsCompact&&editor.IsVisible&&Walk(editor).OfType<TextBox>().Any(t=>t.Text=="模式切换时保留"),"切回完整模式保留打开的编辑器内容");check(!main.Topmost,"完整模式不保持侧栏置顶");editor.Close();
  check(JsonSerializer.Serialize(vm.State,JsonKit.Options)==state,"完成星标字体模式均不改变日程与版本");var saved=new BoardPreferenceStore(vm.DataDirectory).Load();check(saved.FontSize==14&&saved.LayoutMode=="FULL"&&saved.Important.Contains(key)!=important,"不同入口修改偏好互不覆盖");
  vm.UpdateAppearance(p=>p.FontSize=22);await Task.Delay(70);bool tableMeasured=false,deleteReachable=false;var dialogTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};dialogTimer.Tick+=(_,_)=>{var dialog=Application.Current.Windows.OfType<Window>().FirstOrDefault(w=>w.Title=="行程表设置");if(dialog is null)return;dialogTimer.Stop();var scrolling=Walk(dialog).OfType<ScrollViewer>().FirstOrDefault();scrolling?.ScrollToEnd();dialog.UpdateLayout();var delete=ButtonOf(dialog,"删除行程表");var bottom=delete.TransformToAncestor(dialog).Transform(new Point(0,delete.ActualHeight));File.WriteAllText(Path.Combine(directory,"table-geometry.txt"),$"deleteBottom={bottom.Y}; ActualHeight={dialog.ActualHeight}; RenderHeight={dialog.RenderSize.Height}; contentHeight={((FrameworkElement)dialog.Content).ActualHeight}; desiredHeight={((FrameworkElement)dialog.Content).DesiredSize.Height}");Capture(dialog,Path.Combine(directory,"table-large.png"));var client=(FrameworkElement)VisualTreeHelper.GetChild(dialog,0);File.AppendAllText(Path.Combine(directory,"table-geometry.txt"),$"; client={client.GetType().Name}:{client.ActualHeight}");deleteReachable=bottom.Y<=client.ActualHeight-2&&bottom.Y>0;tableMeasured=true;dialog.Close();};dialogTimer.Start();ButtonOf(main,"设置").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));dialogTimer.Stop();check(tableMeasured&&deleteReachable,"22号字体行程表设置底部操作滚动可达");vm.UpdateAppearance(p=>p.FontSize=14);
  var restoreVm=new PlannerViewModel(Path.Combine(directory,"restore-full"),false);restoreVm.UpdateAppearance(p=>{p.LayoutMode="FULL";p.FullWidth=1260;p.FullHeight=760;});var restored=new MainWindow(restoreVm);restored.Show();await Task.Delay(90);bool restoredSize=Math.Abs(restored.Width-1260)<2&&Math.Abs(restored.Height-760)<2;restored.Close();check(restoredSize,"完整模式重启恢复已保存窗口尺寸");
  main.Width=1480;main.Height=920;board.SetView("MONTH");board.NavigateTo(Clock.Today);await Task.Delay(90);Capture(main,Path.Combine(directory,"soft-full-month.png"));board.SetView("LIST");await Task.Delay(70);Capture(main,Path.Combine(directory,"soft-full-list.png"));board.SetView("MONTH");
 }
 static void Swipe(SwipeActivityCard card,double dx,double dy){card.BeginSwipe(new(0,0));card.ContinueSwipe(new(dx,dy));card.EndSwipe();}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Walk(c))yield return d;}
 static Button ButtonOf(DependencyObject root,string name)=>Walk(root).OfType<Button>().First(b=>Equals(b.Content,name));
 static void Capture(Window window,string path){window.UpdateLayout();var e=(FrameworkElement)window.Content;int w=(int)Math.Ceiling(e.ActualWidth),h=(int)Math.Ceiling(e.ActualHeight);var image=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var dc=background.RenderOpen())dc.DrawRectangle(window.Background,null,new Rect(0,0,w,h));image.Render(background);image.Render(e);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(path);png.Save(file);}
}
